      "],["comment"," keyword-gap:start "],["element","http://www.w3.org/1999/xhtml","section",[["","class","section keyword-gap-content"],["","data-keyword-gap",""]],[["element","http://www.w3.org/1999/xhtml","div",[["","class","shell service-reading"]],[["element","http://www.w3.org/1999/xhtml","div",[["","class","keyword-gap-part"],["","id","gap-price-guide-routes"]],[["element","http://www.w3.org/1999/xhtml","h2",[],[["text","Find the price guide for the actual task"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","The service pages contain the existing guide ranges and their conditions. Compare the included work, not just the lowest figure: attendance or investigation, products, installation, access and separate repair can change the scope. Where a fixed guide is not offered, request a property-specific written quote."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Confirm any attendance charge, charges if you do not proceed and the scope of further investigation before booking. These questions do not establish that a fee applies or is waived; the team needs to confirm the terms for the proposed visit."]]],["element","http://www.w3.org/1999/xhtml","ul",[["","class","intent-links"]],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","plumbing.html#gap-plumbing-prices"]],[["text","Plumber costs and quotation scope"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","electrical.html#gap-electrical-prices"]],[["text","Electrician costs and investigation scope"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","blocked-drains-perth.html#service-quote"]],[["text","Blocked-drain clearing price guide"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","hot-water-problems-perth.html#service-quote"]],[["text","Hot-water repair and replacement price guide"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","toilet-repairs-perth.html#service-quote"]],[["text","Toilet repair price guide"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","lighting-power-points-perth.html#service-quote"]],[["text","Lighting and power-point price guide"]]]]]]]]]]]]],["comment"," keyword-gap:end "],["element","http://www.w3.org/1999/xhtml","section",[["","class","section faq"]],[["text","
        "],["element","http://www.w3.org/1999/xhtml","div",[["","class","shell"]],[["text","
          "],["comment"," site-intent:start "],["element","http://www.w3.org/1999/xhtml","div",[["","class","intent-content"],["","data-site-intent",""]],[["element","http://www.w3.org/1999/xhtml","h2",[],[["text","Booking, scope and quotation questions"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Use this page for questions that apply across services. Fault-specific questions belong on the relevant repair page, where the assessment and service boundaries are explained in more detail. You can enquire without naming a faulty part or collecting photos. The team confirms the proposed visit and written scope before agreed work proceeds."]]],["element","http://www.w3.org/1999/xhtml","ul",[["","class","intent-links"]],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","plumbing.html"]],[["text","Choose a plumbing repair"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","electrical.html"]],[["text","Choose electrical repairs or installation"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","property-management.html"]],[["text","Work orders and approval for managed properties"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","lighting-installation-perth.html"]],[["text","Lighting Installation & Repairs Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","power-points-perth.html"]],[["text","Power Point Installation & Repairs Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","dishwasher-installation-perth.html"]],[["text","Dishwasher Installation & Connections Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","toilet-installation-perth.html"]],[["text","Toilet Installation & Replacement Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","shower-plumbing-repairs-perth.html"]],[["text","Shower Plumbing Leak Repairs Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","water-pressure-perth.html"]],[["text","Low Water Pressure & Water Hammer Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","ceiling-fans-perth.html"]],[["text","Ceiling Fan Installation & Repairs Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","exhaust-fans-perth.html"]],[["text","Bathroom Exhaust Fan Replacement Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","switchboard-upgrades-perth.html"]],[["text","Switchboard Repairs & Upgrades Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","rcd-testing-perth.html"]],[["text","RCD Testing & Safety Switch Checks Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","emergency-plumber-perth.html"]],[["text","24-Hour Emergency Plumber Perth questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","emergency-electrician-perth.html"]],[["text","24-Hour Emergency Electrician Perth questions"]]]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Why can an online guide price differ from the written quote?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","A guide range describes a standard scope; the property may need different access, materials, investigation or additional work. Ask the team to identify the inclusions and approval boundaries in the written quote rather than treating an online range as a fixed offer."]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Can I approve investigation without approving every possible repair?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Discuss the initial assessment scope and the person authorised to approve it. If further repair or replacement is proposed, ask what needs separate agreement. An enquiry or access arrangement alone is not approval of unlimited work."]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","What are your routine hours and emergency arrangements?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Routine service hours: 09:00–21:00, seven days a week. 24-hour emergency repairs are available; call to confirm attendance arrangements and the quoted emergency work. No arrival time is guaranteed. Emergency repair fees follow the quoted work plan. For urgent work, call rather than relying on an online enquiry."]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Can a hidden water leak cause a high bill without visible water damage?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Yes, a concealed leak is possible without visible damage. A bill increase alone is insufficient to diagnose one. "],["element","http://www.w3.org/1999/xhtml","a",[["","href","water-leak-detection-perth.html#learn-about-water-leak-detection-perth"]],[["text","Read the explanation."]]]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","What is the difference between an RCD and a circuit breaker?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","An RCD detects leakage imbalance; a circuit breaker responds to overload or short circuit. A combined device can do both. "],["element","http://www.w3.org/1999/xhtml","a",[["","href","safety-switch-tripping-perth.html#learn-about-safety-switch-tripping-perth"]],[["text","Read the explanation."]]]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Why has my hot water suddenly stopped working?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Several supply, heating or plumbing faults can interrupt hot water. The system type and affected outlets guide assessment. "],["element","http://www.w3.org/1999/xhtml","a",[["","href","hot-water-problems-perth.html#learn-about-hot-water-problems-perth"]],[["text","Read the explanation."]]]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","What is the difference between a running toilet and a leaking toilet base?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","A running cistern passes or replenishes water internally; a base leak is external water with a source that needs checking. "],["element","http://www.w3.org/1999/xhtml","a",[["","href","toilet-repairs-perth.html#learn-about-toilet-repairs-perth"]],[["text","Read the explanation."]]]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Who should a tenant contact first about plumbing or electrical repairs?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","For routine repairs, report to the agent or landlord. For immediate danger, use the appropriate emergency channel first. "],["element","http://www.w3.org/1999/xhtml","a",[["","href","property-management.html#learn-about-property-management"]],[["text","Read the explanation."]]]]]]]]],["comment"," site-intent:end "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","What is Ellis Services Group?"]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Ellis Services Group is part of the Ellis Group, with a dedicated
              Perth repair team providing plumbing and electrical repairs and
              maintenance across Perth for homes, rentals, strata properties
              and commercial premises.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Which areas does Ellis Services Group cover?"]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Our dedicated Perth repair team provides plumbing and electrical
              services across Perth. Include the property suburb and service
              required so we can prepare for the work.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","What information should I provide?"]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Provide the property address, affected area, factual description,
              when it began, whether it is active or worsening, and the best
              access contact. Property managers should include a work-order
              reference and approval pathway.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Can I send photos?"]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Photos are optional: email safely taken photos to maxinemaintenance.au@outlook.com. You can contact us without photos. Do not approach exposed wiring, active sparking, wet electrical equipment or another hazard to take a photo.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","
              What if I do not know whether the problem is plumbing or
              electrical?
            "]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Describe what you observe rather than guessing. Our Perth team
              will identify the appropriate plumbing or electrical service path.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","
              Should I use the blocked drain or blocked toilet page?
            "]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Use Blocked Drains & Toilets for slow drainage, gurgling,
              backups or a blocked toilet. Use Toilet Repairs when the concern
              is specifically a running, leaking, slow-filling or
              non-functioning toilet.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","What should I do if a pipe bursts?"]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Put people and electrical safety first. If it is safe and
              familiar, isolate the water supply; otherwise keep clear and use
              the Burst Pipe Repair page to share the affected area and active
              water details.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","
              What should I do if a safety switch keeps tripping?
            "]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Do not repeatedly reset it. Note which areas lost power and what
              equipment was being used. Do not open the switchboard or work on
              fixed wiring.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","When is Ellis Services Group available?"]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Routine service hours: 09:00–21:00, seven days a week. 24-hour emergency repairs are available; call to confirm attendance arrangements and the quoted emergency work. No arrival time is guaranteed.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Are licence details available?"]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Services are provided by appropriately licensed plumbing and electrical tradespeople. Current licence details are available on request for procurement or property management.
            "]]],["text","
          "]]],["text","
          "],["element","http://www.w3.org/1999/xhtml","details",[],[["text","
            "],["element","http://www.w3.org/1999/xhtml","summary",[],[["text","When should I call 000?"]]],["text","
            "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
              Call 000 for life-threatening emergencies, fire, smoke, active
              arcing or immediate danger. Move to a safe location first. Once the immediate hazard is made safe, contact Ellis Services Group to arrange the repair assessment.
            "]]],["text","
          "]]],["text","
        "]]],["text","
      "]]],["text","
    "]]],["text","
    "],["element","http://www.w3.org/1999/xhtml","footer",[["","class","footer"]],[["text","
      "],["element","http://www.w3.org/1999/xhtml","div",[["","class","shell"]],[["text","
        "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","
          Ellis Services Group · 0413 477 667 · maxinemaintenance.au@outlook.com
          · 140 St Georges Terrace, Perth WA 6000
        "]]],["text","
        "],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Services are provided by appropriately licensed plumbing and electrical tradespeople. Licence details are available on request."]]],["text","
      "]]],["text","
