"],["element","http://www.w3.org/1999/xhtml","p",[["","class","shell"],["","data-confirmed-hours",""]],[["text","Routine service hours: 09:00–21:00, seven days a week. 24-hour emergency repairs are available; call to confirm attendance arrangements and the quoted emergency work. No arrival time is guaranteed."]]]]],["text","
