/www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","class","nav-cta"],["","href","contact.html"]],[["text","Contact"]]]]]]]]]]]]],["element","http://www.w3.org/1999/xhtml","main",[["","class","article"]],[["element","http://www.w3.org/1999/xhtml","p",[["","class","breadcrumbs"]],[["element","http://www.w3.org/1999/xhtml","a",[["","href","/"]],[["text","Home"]]],["text"," / "],["element","http://www.w3.org/1999/xhtml","a",[["","href","insights.html"]],[["text","Insights"]]]]],["element","http://www.w3.org/1999/xhtml","header",[["","class","article-header"]],[["element","http://www.w3.org/1999/xhtml","span",[["","class","eyebrow"]],[["text","Plumbing guide"]]],["element","http://www.w3.org/1999/xhtml","h1",[],[["text","Reporting a plumbing leak: inspection and repair in Perth"]]],["element","http://www.w3.org/1999/xhtml","aside",[["","class","intent-safety"],["","data-intent-safety",""]],[["element","http://www.w3.org/1999/xhtml","p",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","Separate private leaks from utility faults."]]],["text"," For water at the meter, see "],["element","http://www.w3.org/1999/xhtml","a",[["","href","https://www.watercorporation.com.au/help-and-advice/water-issues/leaks/leaking-meter"],["","rel","noopener noreferrer"],["","target","_blank"]],[["text","Water Corporation meter guidance"]]],["text",". For wastewater overflow, follow its "],["element","http://www.w3.org/1999/xhtml","a",[["","href","https://www.watercorporation.com.au/Help-and-advice/Water-issues/Wastewater/Sewer-blockage-or-overflow"],["","rel","noopener noreferrer"],["","target","_blank"]],[["text","overflow reporting advice"]]],["text"," before a normal repair request."]]]]],["element","http://www.w3.org/1999/xhtml","p",[["","class","article-meta"]],[["text","Practical property information"]]]]],["element","http://www.w3.org/1999/xhtml","p",[["","class","article-meta"],["","data-editorial-meta",""]],[["text","By "],["element","http://www.w3.org/1999/xhtml","a",[["","href","about.html"]],[["text","Ellis Services Group"]]],["text"," · Updated "],["element","http://www.w3.org/1999/xhtml","time",[["","datetime","2026-10-10"]],[["text","10 October 2026"]]]]],["element","http://www.w3.org/1999/xhtml","aside",[["","class","article-summary"],["","data-editorial-summary",""]],[["element","http://www.w3.org/1999/xhtml","h2",[],[["text","At a glance"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Start with the affected room, when water appeared and whether it is still spreading. Photos and meter records are optional clues. An on-site inspection establishes the source; the written scope should distinguish detection, access, pipe repair and surface restoration. For managed properties, include the access contact and person who can approve the work."]]]]],["element","http://www.w3.org/1999/xhtml","nav",[["","aria-label","In this guide"],["","class","article-toc"]],[["element","http://www.w3.org/1999/xhtml","h2",[],[["text","In this guide"]]],["element","http://www.w3.org/1999/xhtml","ul",[],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-1"]],[["text","Decide what needs attention first"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-2"]],[["text","What to record before the inspection"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-3"]],[["text","How Ellis takes a report through to a repair scope"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-4"]],[["text","Separate pipe repair from access and surface restoration"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-5"]],[["text","For tenants and property managers"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-6"]],[["text","Common leak-reporting questions"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-7"]],[["text","Use the right route for the water source"]]]]]]]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","To report a plumbing leak in Perth, send Ellis Services Group the location, timing, water spread and safe access details. We use that information to plan the inspection, investigate the likely source and explain the repair scope before you authorise further work."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","You do not need to diagnose a hidden pipe fault before calling. A damp ceiling, water under a cabinet or unexplained meter movement gives us a starting point; the inspection determines what needs attention. Our "],["element","http://www.w3.org/1999/xhtml","a",[["","href","water-leak-detection-perth.html"]],[["text","water leak detection service"]]],["text"," explains the signs we investigate and how detection and repairs can be scoped separately."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-1"]],[["text","Decide what needs attention first"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","ul",[],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","A stable drip or stain you can observe safely:"]]],["text"," record the affected room, when it started and whether it follows use of a fixture. Send an enquiry with photos taken from a safe position."]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","Active flow or spreading water:"]]],["text"," call "],["element","http://www.w3.org/1999/xhtml","a",[["","href","tel:+61413477667"]],[["text","0413 477 667"]]],["text"," and describe whether the flow is continuing and which rooms are affected. If you know the water isolation point and it is safe to reach, isolate the supply. Do not delay contact to collect a full set of photos. Our "],["element","http://www.w3.org/1999/xhtml","a",[["","href","burst-pipe-repair-perth.html"]],[["text","burst pipe repair page"]]],["text"," covers active pipe leaks and repair arrangements."]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","Water near electrical fittings, appliances or a switchboard:"]]],["text"," keep people away and do not touch wet equipment, operate switches in the affected area or enter water to reach an isolation point. Tell us about the electrical hazard when you call so the required trades can be considered. For immediate danger to people, contact emergency services."]]]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Move belongings or contain a small visible drip only where it is safe. Do not remove fittings, open walls or climb into a ceiling to find the source. Access work is part of the scope to discuss with the attending tradesperson."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-2"]],[["text","What to record before the inspection"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Start with the address and affected room. Describe where you see water, rather than where you think the pipe is broken: below the kitchen sink, beside the hot-water unit, at the toilet base or on the ceiling below a bathroom. Note whether it is dripping, running or pooling, and whether it appears constantly or only when a fixture is used."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Include the time first noticed, any change in the wet area, staining or swelling, and whether the supply has been isolated. A wide photo can show the location; a closer photo can show the visible detail. Take both without disturbing finishes or approaching electrical hazards. Previous repairs, recent plumbing work and an unusual water bill are useful context, but none proves the cause on its own."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","Use water meter records as a clue"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","If the meter is safely accessible and the situation is stable, note the meter type, readings and times. Water Corporation's "],["element","http://www.w3.org/1999/xhtml","a",[["","href","https://www.watercorporation.com.au/Help-and-advice/Water-issues/Leaks/Detect-a-Leak"]],[["text","household leak-check guidance"]]],["text"," compares ordinary meter readings after actual water use has stopped for 15 minutes. An integrated smart meter uses its own model instructions and usage display; do not apply the ordinary dial-reading method to every meter."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Record any automatic use that could affect the reading, such as irrigation or an appliance. Meter movement can indicate continuing water use. Contact Ellis Services Group for an on-site inspection to locate the source and confirm the repair scope. Do not postpone help for active flooding or an electrical hazard to run a meter check."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-3"]],[["text","How Ellis takes a report through to a repair scope"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","1. Confirm the inspection goal and access"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","We review the affected area, active water flow and any hazard, then arrange the on-site inspection. Our team checks the suspected supply leak, visible connections and surrounding moisture to identify the cause. We confirm the on-site contact, entry arrangements and safe access to the relevant room, meter and fixtures."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","2. Inspect and explain the findings"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Our team investigates the leak on site, identifies the fault and explains the required repair and access work. We select the investigation method for the affected area, explain any opening work, and confirm the work scope and quote before proceeding."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Water Corporation's "],["element","http://www.w3.org/1999/xhtml","a",[["","href","https://www.watercorporation.com.au/help-and-advice/water-issues/leaks/finding-the-right-plumber-to-fix-a-leak"]],[["text","guidance on choosing a plumber for a leak"]]],["text"," explains why hidden leaks need the appropriate skills. Ellis services are provided by appropriately licensed plumbing and electrical tradespeople; licence details are available on request."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","3. Confirm the written scope and approval"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Inspection findings lead to a proposed repair, further investigation or related work. Confirm what the quotation includes before authorising that next stage. If opening a wall or floor reveals a different condition, the additional work and cost need to be explained and approved before the scope expands. For a managed property, establish who can approve costs and how urgent findings should be reported."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","4. Complete the agreed work and record the outcome"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","The repair and agreed checks are completed within the authorised scope. We record the identified fault, work completed and follow-up items. The handover confirms the surface restoration and any related trade work included in your agreed scope."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-4"]],[["text","Separate pipe repair from access and surface restoration"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","A useful quotation makes these items clear:"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","ul",[],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","Inspection or detection:"]]],["text"," the area to investigate, access available and any agreed limit to the initial visit."]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","Access or opening:"]]],["text"," whether cabinetry, a wall, floor or paving needs to be opened, and who is responsible for that work."]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","Pipe or fitting repair:"]]],["text"," the identified component, proposed repair and checks included afterward."]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","Surface restoration:"]]],["text"," whether plaster, paint, tiles, cabinetry or paving reinstatement is included, separately priced or left for another trade."]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","strong",[],[["text","Related work:"]]],["text"," electrical safety, drying or a separate drainage issue where the inspection identifies a need."]]]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Access, concealed pipe routes, the extent of damage and restoration requirements affect the scope. A quote for finding a leak should not be compared directly with a quote that also includes opening, repair and restoring finishes. Send the property details through our "],["element","http://www.w3.org/1999/xhtml","a",[["","href","contact.html"]],[["text","Perth enquiry form"]]],["text"," so our team can arrange an on-site inspection, identify the cause and confirm the repair plan and written quote."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-5"]],[["text","For tenants and property managers"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Include the tenant or on-site contact, entry permission, suitable access times and the person responsible for approving costs. Note the work-order reference, any approval limit and where photos, findings and invoices should be sent. If a room is unavailable or the meter is behind a locked gate, say so before the visit."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","After the work, retain the repair record and any outstanding restoration or reinspection tasks. Our "],["element","http://www.w3.org/1999/xhtml","a",[["","href","property-management.html"]],[["text","property management service"]]],["text"," covers work orders, access notes and approval paths for managed Perth properties."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-6"]],[["text","Common leak-reporting questions"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","Do I need a meter reading before I call?"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","No. Report what you can see safely. A meter record can help with a stable suspected leak, but active water spread or an electrical hazard takes priority over collecting readings."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","Can a photo confirm where the hidden pipe is leaking?"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","A photo shows visible symptoms and access conditions. Water can travel before it becomes visible, so the inspection must establish the source and whether more access is needed."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","Does leak detection include repairing and repainting the wall?"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Only if those tasks are included in the agreed scope. Ask for inspection, opening, pipe repair and surface restoration to be identified separately."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","h3",[],[["text","What should a tenant send to the property manager?"]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Send the address, affected room, timing, active flow and safe photos, plus your contact and access availability. Follow the property's urgent-maintenance process when water is continuing to spread."]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[],[["element","http://www.w3.org/1999/xhtml","a",[["","class","button"],["","href","contact.html"]],[["text","Arrange a leak inspection with Ellis"]]],["text"," or call "],["element","http://www.w3.org/1999/xhtml","a",[["","href","tel:+61413477667"]],[["text","0413 477 667"]]],["text"," with the location, water spread and access details."]]],["element","http://www.w3.org/1999/xhtml","p",[["","class","shell"]],[["text","Photos are optional: email safely taken photos to "],["element","http://www.w3.org/1999/xhtml","a",[["","href","mailto:maxinemaintenance.au@outlook.com"]],[["text","maxinemaintenance.au@outlook.com"]]],["text",". You can contact us without photos. Do not approach a hazard or dismantle equipment to take them."]]],["comment"," site-intent:start "],["element","http://www.w3.org/1999/xhtml","div",[["","class","intent-content"],["","data-site-intent",""]],[["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-7"]],[["text","Use the right route for the water source"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","A suspected private pipe leak, water at the meter and wastewater returning through a drain need different next steps. Report the observation without moving covers or entering water to investigate. If the source is not clear, say so. A useful enquiry separates the location of the symptom from a proposed diagnosis."]]],["element","http://www.w3.org/1999/xhtml","ul",[["","class","intent-links"]],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","water-leak-detection-perth.html"]],[["text","Request private-pipe leak investigation"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","blocked-drains-perth.html"]],[["text","Wastewater and blocked-drain guidance"]]]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Should I treat water at the meter as a normal private-pipe repair?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Not automatically. Follow Water Corporation guidance for the meter and explain where the water appears from a safe position. The supply or meter boundary matters; do not assume every leak belongs to privately maintained plumbing."]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Should I open a wall before the plumber visits?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","No. Explain the visible location and current condition. Investigation, access and restoration should be agreed as parts of the scope; opening finishes yourself may introduce a hazard without establishing the source."]]]]]]],["comment"," site-intent:end "],["element","http://www.w3.org/1999/xhtml","p",[["","data-guide-services",""]],[["text","For a leak centred on a fitting, see "],["element","http://www.w3.org/1999/xhtml","a",[["","href","tap-mixer-repairs-perth.html"]],[["text","tap and mixer repairs"]]],["text"," or "],["element","http://www.w3.org/1999/xhtml","a",[["","href","toilet-repairs-perth.html"]],[["text","toilet and cistern repairs"]]],["text",". Water returning through a drain is a different drainage request: see "],["element","http://www.w3.org/1999/xhtml","a",[["","href","blocked-drains-perth.html"]],[["text","blocked-drain clearing and assessment"]]],["text",". If the source is unclear, describe the observation rather than choosing a diagnosis."]]]]],["element","http://www.w3.org/1999/xhtml","footer",[["","class","footer"]],[["element","http://www.w3.org/1999/xhtml","div",[["","class","shell"]],[["text","Ellis Services Group · 140 St Georges Terrace, Perth WA 6000 · 0413 477 667 · Services are provided by appropriately licensed plumbing and electrical tradespeople. Licence details are available on request."]]],["element","http://www.w3.org/1999/xhtml","p",[["","class","shell"],["","data-business-identity",""]],[["text","ELLIS SERVICES GROUP PTY LTD · "],["element","http://www.w3.org/1999/xhtml","a",[["","href","https://abr.business.gov.au/ABN/View?id=645821745"],["","rel","noopener noreferrer"],["","target","_blank"]],[["text","ABN 96 645 821 745"]]]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[["","class","shell"],["","data-confirmed-hours",""]],[["text","Routine service hours: 09:00–21:00, seven days a week. 24-hour emergency repairs are available; call to confirm attendance arrangements and the quoted emergency work. No arrival time is guaranteed."]]]]],["element","http://www.w3.org/1999/xhtml","script",[["","src","site.js"]],[]],["element","http://www.w3.org/1999/xhtml","script",[["","src","navigation.js"]],[]],["text","
"]]]]]]]

