      "@type": "Article",
      "headline": "A clear maintenance handover between tenants and property managers",
      "description": "A tenant-to-manager maintenance handover for Perth properties: record symptoms, changes and approval responsibility without asking occupants to diagnose faults.",
      "url": "https://perthpipepower.com.au/insights-tenant-property-manager-maintenance-handover.html",
      "inLanguage": "en-AU",
      "author": {
        "@id": "https://perthpipepower.com.au/#business"
      },
      "publisher": {
        "@id": "https://perthpipepower.com.au/#business"
      },
      "@id": "https://perthpipepower.com.au/insights-tenant-property-manager-maintenance-handover.html#article",
      "mainEntityOfPage": {
        "@id": "https://perthpipepower.com.au/insights-tenant-property-manager-maintenance-handover.html#webpage"
      },
      "dateModified": "2026-10-10",
      "abstract": "Keep the occupant’s original observations with the property reference, access contact and authorised decision-maker. Update the record if the condition changes. Entry permission and approval of repair costs are separate responsibilities. Keep the agreed quote, completed work and outstanding recommendations together so the next person receives a clear handover."
    },
    {
      "@type": "FAQPage",
      "@id": "https://perthpipepower.com.au/insights-tenant-property-manager-maintenance-handover.html#faq",
      "url": "https://perthpipepower.com.au/insights-tenant-property-manager-maintenance-handover.html",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Who should a tenant contact before an ordinary repair booking?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Use the property manager or owner repair-reporting process and provide the factual observation and current condition. Do not assume that reporting a fault gives authority to approve costs. Immediate danger needs the appropriate emergency route first."
          }
        },
        {
          "@type": "Question",
          "name": "Does agreeing access also approve the repair cost?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. Record entry permission and authority to approve work separately. The nominated decision-maker and any agreed limits should travel with the request."
          }
        }
      ]
    }
