      "publisher": {
        "@id": "https://perthpipepower.com.au/#business"
      },
      "@id": "https://perthpipepower.com.au/news-clearer-property-maintenance-enquiry.html#article",
      "mainEntityOfPage": {
        "@id": "https://perthpipepower.com.au/news-clearer-property-maintenance-enquiry.html#webpage"
      },
      "dateModified": "2026-10-10",
      "abstract": "Begin with the property location, affected room and current symptom. You can request an assessment without diagnosing the fault or collecting photos. Explain whether you need a repair or a planned installation. Ellis uses the reported work and access arrangements to plan the assessment and confirm the proposed work in a written quote."
    },
    {
      "@type": "FAQPage",
      "@id": "https://perthpipepower.com.au/news-clearer-property-maintenance-enquiry.html#faq",
      "url": "https://perthpipepower.com.au/news-clearer-property-maintenance-enquiry.html",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Can I send an enquiry before I have all the equipment details?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Yes. Start with the address, current symptom and contact. Say which details are not yet available. Do not dismantle equipment or delay appropriate emergency action to complete a checklist."
          }
        },
        {
          "@type": "Question",
          "name": "Should the first message name the part I want replaced?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Only if it is a planned installation or an existing confirmed instruction. For an unexplained fault, describe the observation so the assessment is not limited by an unsupported diagnosis."
          }
        }
      ]
    }
