/www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","class","nav-cta"],["","href","contact.html"]],[["text","Contact"]]]]]]]]]]]]],["element","http://www.w3.org/1999/xhtml","main",[["","class","article"]],[["element","http://www.w3.org/1999/xhtml","p",[["","class","breadcrumbs"]],[["element","http://www.w3.org/1999/xhtml","a",[["","href","/"]],[["text","Home"]]],["text"," / "],["element","http://www.w3.org/1999/xhtml","a",[["","href","news.html"]],[["text","News"]]]]],["element","http://www.w3.org/1999/xhtml","header",[["","class","article-header"]],[["element","http://www.w3.org/1999/xhtml","span",[["","class","eyebrow"]],[["text","Company update"]]],["element","http://www.w3.org/1999/xhtml","h1",[],[["text","A clearer way to send a property maintenance enquiry"]]]]],["element","http://www.w3.org/1999/xhtml","p",[["","class","article-meta"],["","data-editorial-meta",""]],[["text","By "],["element","http://www.w3.org/1999/xhtml","a",[["","href","about.html"]],[["text","Ellis Services Group"]]],["text"," · Updated "],["element","http://www.w3.org/1999/xhtml","time",[["","datetime","2026-10-10"]],[["text","10 October 2026"]]]]],["element","http://www.w3.org/1999/xhtml","aside",[["","class","article-summary"],["","data-editorial-summary",""]],[["element","http://www.w3.org/1999/xhtml","h2",[],[["text","At a glance"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Begin with the property location, affected room and current symptom. You can request an assessment without diagnosing the fault or collecting photos. Explain whether you need a repair or a planned installation. Ellis uses the reported work and access arrangements to plan the assessment and confirm the proposed work in a written quote."]]]]],["element","http://www.w3.org/1999/xhtml","nav",[["","aria-label","In this guide"],["","class","article-toc"]],[["element","http://www.w3.org/1999/xhtml","h2",[],[["text","In this guide"]]],["element","http://www.w3.org/1999/xhtml","ul",[],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-1"]],[["text","Start with facts"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-2"]],[["text","Choose a service starting point without diagnosing the fault"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-3"]],[["text","State the current condition and property location"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-4"]],[["text","From first contact to an agreed visit and quote"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-5"]],[["text","A useful first message can be brief"]]]]]]]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Useful maintenance information keeps the property address, observable issue, current status, access arrangements and approval contact together. It reduces the chance that an important detail is separated from the request."]]],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-1"]],[["text","Start with facts"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Describe what is happening rather than assuming a cause. Include when it began, whether it is changing, and whether there is an immediate safety concern. Property managers can add the work-order reference and nominated decision-maker."]]],["element","http://www.w3.org/1999/xhtml","div",[["","data-seo-guide-expansion",""]],[["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-2"]],[["text","Choose a service starting point without diagnosing the fault"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","You can request service from an observed problem: a backed-up sink, visible water, loss of hot water or lights that have stopped working. Start with the affected area and what changed. You do not need to know which part has failed or which repair method will be used."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Choose "],["element","http://www.w3.org/1999/xhtml","a",[["","href","blocked-drains-perth.html"]],[["text","blocked drain clearing"]]],["text"," for drainage backing up, "],["element","http://www.w3.org/1999/xhtml","a",[["","href","water-leak-detection-perth.html"]],[["text","water leak detection"]]],["text"," for unexplained moisture or leaking pipework, or "],["element","http://www.w3.org/1999/xhtml","a",[["","href","power-faults-perth.html"]],[["text","electrical fault finding"]]],["text"," for reported power faults. If the issue spans plumbing and electrical equipment, describe both observations so the relevant trades can be considered."]]],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-3"]],[["text","State the current condition and property location"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Include the suburb or address, affected room and when the issue started. Say whether water is still flowing, whether a fault is recurring or whether the service has stopped completely. These details help define the assessment request without requiring an occupant to test equipment."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","For a planned installation, explain what you want connected or changed and where it will be used. Do not describe an appliance connection or new lighting location as a fault if it is an improvement request. This helps distinguish investigation from installation when the work is quoted."]]],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-4"]],[["text","From first contact to an agreed visit and quote"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Our local team reviews the reported work, confirms the relevant access contact and arranges the on-site assessment. The findings determine the proposed repair or installation scope. You receive a written quote for the agreed work, with additional requirements explained before they proceed."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","This page is about making the initial request. Managers preparing a formal instruction can use our "],["element","http://www.w3.org/1999/xhtml","a",[["","href","news-useful-property-work-order.html"]],[["text","work-order guide"]]],["text","; entry details belong in the "],["element","http://www.w3.org/1999/xhtml","a",[["","href","news-keeping-access-information-together.html"]],[["text","access checklist"]]],["text",". "],["element","http://www.w3.org/1999/xhtml","a",[["","href","contact.html"]],[["text","Request your Perth service assessment"]]],["text"," or call "],["element","http://www.w3.org/1999/xhtml","a",[["","href","tel:0413477667"]],[["text","0413 477 667"]]],["text",". For immediate danger, move to safety and call 000."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Photos are optional: email safely taken photos to "],["element","http://www.w3.org/1999/xhtml","a",[["","href","mailto:maxinemaintenance.au@outlook.com"]],[["text","maxinemaintenance.au@outlook.com"]]],["text",". You can contact us without photos."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["element","http://www.w3.org/1999/xhtml","a",[["","class","button"],["","href","contact.html"]],[["text","Arrange an on-site assessment & written quote"]]]]]]],["comment"," site-intent:start "],["element","http://www.w3.org/1999/xhtml","div",[["","class","intent-content"],["","data-site-intent",""]],[["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-5"]],[["text","A useful first message can be brief"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Give the property location, affected item, observed change and best contact. If there is a previous job reference, include it as history rather than an assumed diagnosis. Separate a request to investigate from a request to install a particular product; the team can then confirm what the proposed visit needs to cover."]]],["element","http://www.w3.org/1999/xhtml","ul",[["","class","intent-links"]],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","contact.html"]],[["text","Send the initial repair enquiry"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","insights-tenant-property-manager-maintenance-handover.html"]],[["text","Hand over an occupant report"]]]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Can I send an enquiry before I have all the equipment details?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Yes. Start with the address, current symptom and contact. Say which details are not yet available. Do not dismantle equipment or delay appropriate emergency action to complete a checklist."]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Should the first message name the part I want replaced?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Only if it is a planned installation or an existing confirmed instruction. For an unexplained fault, describe the observation so the assessment is not limited by an unsupported diagnosis."]]]]]]],["comment"," site-intent:end "]]],["element","http://www.w3.org/1999/xhtml","footer",[["","class","footer"]],[["element","http://www.w3.org/1999/xhtml","div",[["","class","shell"]],[["text","Ellis Services Group · 140 St Georges Terrace, Perth WA 6000 · 0413 477 667 · Services are provided by appropriately licensed plumbing and electrical tradespeople. Licence details are available on request."]]],["element","http://www.w3.org/1999/xhtml","p",[["","class","shell"],["","data-business-identity",""]],[["text","ELLIS SERVICES GROUP PTY LTD · "],["element","http://www.w3.org/1999/xhtml","a",[["","href","https://abr.business.gov.au/ABN/View?id=645821745"],["","rel","noopener noreferrer"],["","target","_blank"]],[["text","ABN 96 645 821 745"]]]]],["text","
