/www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","class","nav-cta"],["","href","contact.html"]],[["text","Contact"]]]]]]]]]]]]],["element","http://www.w3.org/1999/xhtml","main",[["","class","article"]],[["element","http://www.w3.org/1999/xhtml","p",[["","class","breadcrumbs"]],[["element","http://www.w3.org/1999/xhtml","a",[["","href","/"]],[["text","Home"]]],["text"," / "],["element","http://www.w3.org/1999/xhtml","a",[["","href","news.html"]],[["text","News"]]]]],["element","http://www.w3.org/1999/xhtml","header",[["","class","article-header"]],[["element","http://www.w3.org/1999/xhtml","span",[["","class","eyebrow"]],[["text","Company update"]]],["element","http://www.w3.org/1999/xhtml","h1",[],[["text","Keeping access information with the repair request"]]]]],["element","http://www.w3.org/1999/xhtml","p",[["","class","article-meta"],["","data-editorial-meta",""]],[["text","By "],["element","http://www.w3.org/1999/xhtml","a",[["","href","about.html"]],[["text","Ellis Services Group"]]],["text"," · Updated "],["element","http://www.w3.org/1999/xhtml","time",[["","datetime","2026-10-10"]],[["text","10 October 2026"]]]]],["element","http://www.w3.org/1999/xhtml","aside",[["","class","article-summary"],["","data-editorial-summary",""]],[["element","http://www.w3.org/1999/xhtml","h2",[],[["text","At a glance"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Confirm access to the equipment as well as entry to the property. Provide the current on-site contact, agreed entry arrangements and any restricted areas. Keep changes with the booking record. Share sensitive access information through an agreed private channel, and identify the separate contact authorised to approve repair costs."]]]]],["element","http://www.w3.org/1999/xhtml","nav",[["","aria-label","In this guide"],["","class","article-toc"]],[["element","http://www.w3.org/1999/xhtml","h2",[],[["text","In this guide"]]],["element","http://www.w3.org/1999/xhtml","ul",[],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-1"]],[["text","Share only what is needed"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-2"]],[["text","Confirm entry to the property and to the equipment"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-3"]],[["text","Use a named contact and update changed arrangements"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-4"]],[["text","Protect private information while arranging the repair"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","#guide-5"]],[["text","Confirm access to the equipment as well as the property"]]]]]]]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Property access can influence how a maintenance enquiry is coordinated. Include the on-site contact, notice requirements, building-entry information, parking notes and any relevant strata or building-management detail with the issue description."]]],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-1"]],[["text","Share only what is needed"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Avoid including unnecessary sensitive information. Access codes and occupant information should be shared through an appropriate channel and only for the service request."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","When the scope or access arrangements change, update the same request record so people are working from the current information."]]],["element","http://www.w3.org/1999/xhtml","div",[["","data-seo-guide-expansion",""]],[["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-2"]],[["text","Confirm entry to the property and to the equipment"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Access to the front door is not always access to the installation. A hot-water unit may be behind a locked gate, a fixture may be inside an occupied room and a shared equipment area may need building-management coordination. Tell the service team which relevant spaces can be reached and who will provide entry."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","For apartments, include the unit and building reference, concierge or lift arrangements and practical parking instructions. For other premises, provide gate or site-contact arrangements. Do not enter a hazardous or restricted area to check access; advise us of the restriction so the visit can be planned."]]],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-3"]],[["text","Use a named contact and update changed arrangements"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Identify the person who can answer the door or coordinate the visit, and who should be contacted if the agreed entry arrangements change. Keep the current access window and instructions with the same booking record rather than scattering updates across unrelated messages."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Access permission and repair-cost approval are separate matters. An occupant who provides entry may not be authorised to approve extra work. Use our "],["element","http://www.w3.org/1999/xhtml","a",[["","href","news-useful-property-work-order.html"]],[["text","work-order approval guide"]]],["text"," to record the decision-maker alongside the repair scope."]]],["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-4"]],[["text","Protect private information while arranging the repair"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Share only the personal and access information necessary for the service visit. Do not publish keys, entry codes, occupant schedules or identity documents on a public page or photograph. Ask the service contact which private channel is appropriate for sensitive entry instructions."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","You can begin with the address and fault description even if access is still being arranged. Our "],["element","http://www.w3.org/1999/xhtml","a",[["","href","property-management.html"]],[["text","Perth property maintenance service"]]],["text"," coordinates the relevant contact and approved scope. For a "],["element","http://www.w3.org/1999/xhtml","a",[["","href","hot-water-problems-perth.html"]],[["text","hot-water repair"]]],["text"," or "],["element","http://www.w3.org/1999/xhtml","a",[["","href","fixtures-appliances-perth.html"]],[["text","fixture connection"]]],["text",", mention the equipment location as well as the property entry arrangements."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Photos are optional: email safely taken photos to "],["element","http://www.w3.org/1999/xhtml","a",[["","href","mailto:maxinemaintenance.au@outlook.com"]],[["text","maxinemaintenance.au@outlook.com"]]],["text",". You can contact us without photos."]]],["element","http://www.w3.org/1999/xhtml","p",[],[["element","http://www.w3.org/1999/xhtml","a",[["","class","button"],["","href","contact.html"]],[["text","Arrange an on-site assessment & written quote"]]]]]]],["comment"," site-intent:start "],["element","http://www.w3.org/1999/xhtml","div",[["","class","intent-content"],["","data-site-intent",""]],[["element","http://www.w3.org/1999/xhtml","h2",[["","id","guide-5"]],[["text","Confirm access to the equipment as well as the property"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Entry through the front door may not provide access to the affected room, fixture or installation. Name the on-site contact and explain any agreed building arrangements. If availability changes, update the request promptly. Share private entry details through the agreed contact method, not in public photos or open pages."]]],["element","http://www.w3.org/1999/xhtml","ul",[["","class","intent-links"]],[["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","news-useful-property-work-order.html"]],[["text","Keep approval with the work order"]]]]],["element","http://www.w3.org/1999/xhtml","li",[],[["element","http://www.w3.org/1999/xhtml","a",[["","href","property-management.html"]],[["text","Coordinate a managed-property visit"]]]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","What if the occupant cannot attend the agreed visit?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Contact the team to update access arrangements rather than assuming the original instruction remains workable. Confirm who will provide entry and whether access to the actual equipment is available."]]]]],["element","http://www.w3.org/1999/xhtml","details",[],[["element","http://www.w3.org/1999/xhtml","summary",[],[["text","Should I put alarm codes or keys in the enquiry form?"]]],["element","http://www.w3.org/1999/xhtml","p",[],[["text","Do not include unnecessary sensitive entry information in a general enquiry. Confirm with the team how any required private access details will be shared for the agreed visit."]]]]]]],["comment"," site-intent:end "]]],["element","http://www.w3.org/1999/xhtml","footer",[["","class","footer"]],[["element","http://www.w3.org/1999/xhtml","div",[["","class","shell"]],[["text","Ellis Services Group · 140 St Georges Terrace, Perth WA 6000 · 0413 477 667 · Services are provided by appropriately licensed plumbing and electrical tradespeople. Licence details are available on request."]]],["element","http://www.w3.org/1999/xhtml","p",[["","class","shell"],["","data-business-identity",""]],[["text","ELLIS SERVICES GROUP PTY LTD · "],["element","http://www.w3.org/1999/xhtml","a",[["","href","https://abr.business.gov.au/ABN/View?id=645821745"],["","rel","noopener noreferrer"],["","target","_blank"]],[["text","ABN 96 645 821 745"]]]]],["text","
"],["element","http://www.w3.org/1999/xhtml","p",[["","class","shell"],["","data-confirmed-hours",""]],[["text","Routine service hours: 09:00–21:00, seven days a week. 24-hour emergency repairs are available; call to confirm attendance arrangements and the quoted emergency work. No arrival time is guaranteed."]]]]],["element","http://www.w3.org/1999/xhtml","script",[["","src","site.js"]],[]],["element","http://www.w3.org/1999/xhtml","script",[["","src","navigation.js"]],[]],["text","
