      "@id": "https://perthpipepower.com.au/news-useful-property-work-order.html#article",
      "mainEntityOfPage": {
        "@id": "https://perthpipepower.com.au/news-useful-property-work-order.html#webpage"
      },
      "dateModified": "2026-10-10",
      "abstract": "List each room, fixture and observed problem separately. Identify who may approve the visit, repairs and additional findings. Ask the quote to distinguish investigation, repair and related access work. Close the record with what was actually completed and any follow-up recommendations; an inspection or recommendation is not a completed repair."
    },
    {
      "@type": "FAQPage",
      "@id": "https://perthpipepower.com.au/news-useful-property-work-order.html#faq",
      "url": "https://perthpipepower.com.au/news-useful-property-work-order.html",
      "mainEntity": [
        {
          "@type": "Question",
          "name": "Is a spending limit enough to define a work order?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "No. State the requested assessment or work, the property, any exclusions and who can approve changes. A limit alone does not explain which task is authorised."
          }
        },
        {
          "@type": "Question",
          "name": "What should happen if the assessment changes the proposed repair?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "Record the finding and revised scope against the same work-order reference. Follow the nominated approval pathway before assuming that the original instruction covers additional or different work."
          }
        }
      ]
    }
