    {
      "@type": "Service",
      "name": "Electrical Fault Finding & Power Repairs Perth",
      "description": "Electrical fault finding and power repairs in Perth for outages, circuit faults and recurring trips. Book a licensed electrician assessment and written quote.",
      "serviceType": "Electrical Fault Finding & Power Repairs Perth",
      "areaServed": {
        "@type": "City",
        "name": "Perth"
      },
      "@id": "https://perthpipepower.com.au/power-faults-perth.html#service",
